import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"楊氏易傳","description":"楊氏易傳 - 楊氏易傳","frontmatter":{"title":"楊氏易傳","description":"楊氏易傳 - 楊氏易傳"},"headers":[],"relativePath":"classics/yangshi/001.md","filePath":"classics/yangshi/001.md"}'),r={name:"classics/yangshi/001.md"};function i(c,a,o,p,d,m){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"楊氏易傳",tabindex:"-1"},[l("楊氏易傳 "),e("a",{class:"header-anchor",href:"#楊氏易傳","aria-label":"Permalink to “楊氏易傳”"},"​")],-1),e("p",null,"欽定四庫全書經部一",-1),e("p",null,"易類提要",-1),e("p",null,"臣 等謹案：楊氏易傳二十卷，宋楊簡撰。簡字敬仲，慈谿人。乾道五年進士，官至寶謨閣學士、太中大夫。是書為明劉日升、陳道亨所校刻。案朱彝尊經義考載慈湖易解十卷，又己易一卷，書名、卷數皆與此本不合。所載自序一篇，與此本卷首題語相同，而無其前數行，亦為小異。明人凡刻古書，必以私意竄亂之，萬曆以後尤甚。此或日升等所妄改歟？其書前十九卷皆解經文，第二十卷則皆泛論易學之語，亦間有與序文相復者。今既不睹簡之原本，亦莫詳其何故也。簡之學出陸九淵，故其解易惟以人心為主，而象數事物皆在所略，甚至謂繋辭中「近取諸身」一節為不知道者所偽作，非孔子之言。故明楊時喬作傳易考，竟斥為異端。而元董真卿論林栗易解，亦引朱子語錄稱「楊敬仲文字可毀」云云。豈非簡之騖談高遠，有以致之乎？考自漢以來，以老莊說易者，始魏王弼；以心性說易者，始王宗傳及簡。宗傳，淳熙中進士；簡，乾道中進士，皆孝宗時人也。顧宗傳人微言輕，其書僅存，不為學者所誦習。簡則為象山弟子之冠，如朱門之有黃幹，又歷官中外，政績卓有可觀，在南宋為名臣，尤足以籠罩一世。故至於明季，其說大行。紫溪蘇濬解易，遂以冥冥篇為名，而易全入禪矣。夫易之為書，廣大悉備，聖人之為教，精粗本末，兼該心性之理，未嘗不蘊易中。特簡等專明此義，遂流於恍惚虛無耳。昔朱子作儀禮經傳通解，不刪鄭康成所引讖緯之說，謂「存之正所以廢之」。蓋其名既重，不存其說，人無由知其失也。今錄簡及宗傳之易，亦猶是義雲。乾隆四十四年六月恭校上。",-1),e("p",null,"總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。楊氏易傳原序",-1),e("p",null,"昨秋餘入南銓選部，陳君以所刻蘇長公易傳相示，餘讀而卒業，已謂奇矣。頃之，封司劉君、功司陳君復刻楊敬仲易傳成，屬餘敘。餘讀之，又一奇也。獨斯傳也，明所學也。餘不學，其何敢序？然學不可以終棄，則傳言學者不敢不致意也，敘何可已。夫易道大矣，自周、孔而後，微言絕而程朱傳行，謂可以盡易，而易有所不可盡也。今觀蘇氏傳，雖未必盡合易旨，然借易以發其自有之奇，其識雋，其文雄，往往道人所未經道，其卒傳宜也。楊氏因易之理以發攄其所學，精深融貫，要在一而能通，示人專事內而不外，非直探本原者能之乎？要之，蘇即事以明理，楊溯源以該流。譬之蘇如樝梨橘柚雜陳而皆適於口，楊則即一樝梨橘柚，而凡為樝梨橘柚之類者，皆可推而味之也。是二氏俱深於易，求其有補於學，楊視蘇為要焉。抑楊氏始因象山先生舉扇柄而得其本心，遂悟所學，乃發為易傳，於乾有曰：「君子自強不息者，即天行之健也，非天行之健在彼，而君子效之於此也。」又曰：「子思不曰誠者自誠，而曰自成，是於誠實之外復起自成之意，失其誠矣。」斯語也，亦猶是心也。唯是健不必效，而誠不必成，或疑允若茲，是人皆天也，不必復益以人力也，不幾於溺人以虛乎？然善語道者必反其本，善察言者必抉其要。慈湖先生嘗雲：「少讀易大傳，唯愛無思也，無為也，寂然不動，感而遂通天下之故。故其傳益，則以善之不能為，過之難改，皆始於意。意本於我，知我本無體，復何遷而何改？」傳震又曰：人唯知恐懼修省，學者事耳，謂易道精微不在是。持是見者，不惟不知易，亦不知恐懼修省。夫曰「不能為」，曰「難改」，曰「恐懼修省」，則何嘗不責人之致力，特其所以致者，在何思何慮而不失其寂然者耳。蓋用力於其本，而不泛用者也。譬之操舟者然，順流帆風，楫櫂隨之，瞬息千里，是不操之操，操更力耳。庸可以無操之跡，遂謂其不操舟也？審然者，不惟益易，且益學者哉！籲！此與蘇傳均易之羽翼也，顧湮沒久矣，待三君而始傳，信大寶之顯晦有時哉！然一時並顯，而三君與諸同官之志於易，及易道之益明可覘矣。獨愧餘莫為倡，其獨無入山舍玉之懼乎？茲敘也，並以自勖雲。蔡國珍序。",-1)])])}const f=s(r,[["render",i]]);export{_ as __pageData,f as default};
